    links_followed = 0

    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    while remaining:
        components = remaining.split('/', 1)
        component = components[0]
        remaining = components[1] if len(components) > 1 else ''

        if component == '' or component == '.':
            continue
        elif component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
        else:
