                    current = '/'
                    target = target[1:]
                else:
                    if candidate == '/':
                        current = '/'
                    else:
                        current = candidate.rsplit('/', 1)[0]

                remaining = target + ('/' + remaining if remaining else '')
            else:
                current = candidate

    return current

